import { openDB, IDBPDatabase } from 'idb'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

export interface Habit {
  id: string
  name: string
  emoji: string
  color: string
  createdAt: number
}

export interface HabitLog {
  id: string
  habitId: string
  date: string // YYYY-MM-DD
  completed: boolean
}

export interface MoodLog {
  id: string
  date: string // YYYY-MM-DD
  mood: number // 1-5
  note?: string
}

let _db: IDBPDatabase | null = null

export async function getDB(): Promise<IDBPDatabase> {
  if (_db) return _db
  _db = await openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('habits')) {
        const habitStore = db.createObjectStore('habits', { keyPath: 'id' })
        habitStore.createIndex('createdAt', 'createdAt')
      }
      if (!db.objectStoreNames.contains('habitLogs')) {
        const logStore = db.createObjectStore('habitLogs', { keyPath: 'id' })
        logStore.createIndex('habitId', 'habitId')
        logStore.createIndex('date', 'date')
      }
      if (!db.objectStoreNames.contains('moodLogs')) {
        const moodStore = db.createObjectStore('moodLogs', { keyPath: 'id' })
        moodStore.createIndex('date', 'date')
      }
    }
  })
  return _db
}

// Habits
export async function getAllHabits(): Promise<Habit[]> {
  const db = await getDB()
  return db.getAllFromIndex('habits', 'createdAt')
}

export async function saveHabit(habit: Habit): Promise<void> {
  const db = await getDB()
  await db.put('habits', habit)
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB()
  await db.delete('habits', id)
  // Also delete associated logs
  const logs = await db.getAllFromIndex('habitLogs', 'habitId', id)
  const tx = db.transaction(['habitLogs'], 'readwrite')
  for (const log of logs) await tx.store.delete(log.id)
  await tx.done
}

// Habit logs
export async function getLogForDate(habitId: string, date: string): Promise<HabitLog | null> {
  const db = await getDB()
  const logs = await db.getAllFromIndex('habitLogs', 'date', date)
  return logs.find(l => l.habitId === habitId) ?? null
}

export async function getAllLogsForDate(date: string): Promise<HabitLog[]> {
  const db = await getDB()
  return db.getAllFromIndex('habitLogs', 'date', date)
}

export async function saveHabitLog(log: HabitLog): Promise<void> {
  const db = await getDB()
  await db.put('habitLogs', log)
}

// Mood logs
export async function getMoodForDate(date: string): Promise<MoodLog | null> {
  const db = await getDB()
  const logs = await db.getAllFromIndex('moodLogs', 'date', date)
  return logs[0] ?? null
}

export async function saveMoodLog(log: MoodLog): Promise<void> {
  const db = await getDB()
  await db.put('moodLogs', log)
}

// Stats helpers
export function getStreak(habits: Habit[], logs: HabitLog[]): Record<string, { current: number; longest: number }> {
  const result: Record<string, { current: number; longest: number }> = {}
  for (const habit of habits) {
    const habitLogs = logs.filter(l => l.habitId === habit.id).sort((a, b) => a.date.localeCompare(b.date))
    let current = 0
    let longest = 0
    let streak = 0
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    // Check from today backwards
    for (let i = 0; i < 365; i++) {
      const d = new Date(today)
      d.setDate(d.getDate() - i)
      const dateStr = d.toISOString().split('T')[0]
      const log = habitLogs.find(l => l.date === dateStr)
      if (log?.completed) {
        if (i === 0 || (habitLogs.find(l => l.date === new Date(today).toISOString().split('T')[0] - i * 86400000).toISOString().split('T')[0]) === dateStr) {
          // Continue streak if consecutive
        }
        streak++
        longest = Math.max(longest, streak)
      } else {
        if (i === 0) {
          // Today not completed yet, current streak is whatever we have
        } else if (i === 1 && habitLogs.find(l => l.date === new Date(today).toISOString().split('T')[0])) {
          // Yesterday completed but today not - current is 0, longest already recorded
        } else {
          if (i === 1 && !habitLogs.find(l => l.date === new Date(today).toISOString().split('T')[0])) {
            // Today not done, streak broken at today
          } else if (i > 1) {
            // Streak broken
            streak = 0
          }
        }
      }
    }
    // Simpler approach: compute current streak from today backwards
    streak = 0
    for (let i = 0; i < 365; i++) {
      const d = new Date(today)
      d.setDate(d.getDate() - i)
      const dateStr = d.toISOString().split('T')[0]
      const log = habitLogs.find(l => l.date === dateStr)
      if (log?.completed) {
        streak++
      } else {
        if (i > 0) break // today not done yet, or streak broken
        // If i === 0 and not completed, streak is 0 (or we count from yesterday)
        if (i === 0) {
          // Check if yesterday was completed to determine if streak continues
        }
        break
      }
    }
    // Recalculate properly
    let cur = 0
    let lon = 0
    let run = 0
    const sortedDates = [...new Set(habitLogs.filter(l => l.completed).map(l => l.date))].sort().reverse()
    // Current streak: consecutive days ending today or yesterday
    const todayStr = new Date().toISOString().split('T')[0]
    const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0]
    if (sortedDates[0] === todayStr || sortedDates[0] === yesterday) {
      cur = 1
      for (let i = 1; i < sortedDates.length; i++) {
        const prev = new Date(new Date(sortedDates[i - 1]).getTime() - 86400000).toISOString().split('T')[0]
        if (sortedDates[i] === prev) {
          cur++
        } else {
          break
        }
      }
    }
    // Longest streak
    run = 0
    let prevDate: string | null = null
    for (const dateStr of sortedDates.sort()) {
      if (prevDate) {
        const prev = new Date(new Date(prevDate).getTime() - 86400000).toISOString().split('T')[0]
        if (dateStr === prev) {
          run++
        } else {
          lon = Math.max(lon, run)
          run = 1
        }
      } else {
        run = 1
      }
      prevDate = dateStr
    }
    lon = Math.max(lon, run)
    result[habit.id] = { current: cur, longest: lon }
  }
  return result
}

