// Stats helpers
export function getStreak(habits: Habit[], logs: HabitLog[]): Record<string, { current: number; longest: number }> {
  const result: Record<string, { current: number; longest: number }> = {}

  for (const habit of habits) {
    const completedDates = [...new Set(
      logs.filter(l => l.habitId === habit.id && l.completed).map(l => l.date)
    )].sort()

    if (completedDates.length === 0) {
      result[habit.id] = { current: 0, longest: 0 }
      continue
    }

    // Current streak: consecutive days ending today or yesterday
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const todayStr = today.toISOString().split('T')[0]
    const yesterday = new Date(today.getTime() - 86400000).toISOString().split('T')[0]

    let current = 0
    if (completedDates.includes(todayStr)) {
      current = 1
      let d = new Date(today.getTime() - 86400000)
      while (true) {
        const ds = d.toISOString().split('T')[0]
        if (completedDates.includes(ds)) {
          current++
          d = new Date(d.getTime() - 86400000)
        } else {
          break
        }
      }
    } else if (completedDates.includes(yesterday)) {
      current = 1
      let d = new Date(today.getTime() - 86400000 * 2)
      while (true) {
        const ds = d.toISOString().split('T')[0]
        if (completedDates.includes(ds)) {
          current++
          d = new Date(d.getTime() - 86400000)
        } else {
          break
        }
      }
    }

    // Longest streak
    let longest = 0
    let run = 1
    for (let i = 1; i < completedDates.length; i++) {
      const prev = new Date(new Date(completedDates[i - 1]).getTime() - 86400000).toISOString().split('T')[0]
      if (completedDates[i] === prev) {
        run++
      } else {
        longest = Math.max(longest, run)
        run = 1
      }
    }
    longest = Math.max(longest, run)

    result[habit.id] = { current, longest }
  }

  return result
}

import { useState, useEffect, useCallback } from 'react'
import Today from './components/Today'
import Week from './components/Week'
import Settings from './components/Settings'
import { getAllHabits, getAllLogsForDate, getMoodForDate, saveHabitLog, saveMoodLog } from './db'
import { Habit, HabitLog, MoodLog } from './types'

type Tab = 'today' | 'week' | 'settings'

export default function App() {
  const [activeTab, setActiveTab] = useState<Tab>('today')
  const [habits, setHabits] = useState<Habit[]>([])
  const [logs, setLogs] = useState<HabitLog[]>([])
  const [mood, setMood] = useState<MoodLog | null>(null)
  const [dark, setDark] = useState(() => {
    const saved = localStorage.getItem('rhythm-dark')
    if (saved !== null) return saved === 'true'
    return window.matchMedia('(prefers-color-scheme: dark)').matches
  })

  const todayStr = new Date().toISOString().split('T')[0]

  const loadData = useCallback(async () => {
    const [h, l, m] = await Promise.all([
      getAllHabits(),
      getAllLogsForDate(todayStr),
      getMoodForDate(todayStr)
    ])
    setHabits(h)
    setLogs(l)
    setMood(m)
  }, [todayStr])

  useEffect(() => {
    loadData()
  }, [loadData])

  useEffect(() => {
    document.documentElement.classList.toggle('dark', dark)
    localStorage.setItem('rhythm-dark', String(dark))
  }, [dark])

  const toggleHabit = async (habitId: string, date: string) => {
    const existing = await getLogForDate(habitId, date)
    const newCompleted = !existing?.completed
    const log: HabitLog = {
      id: `${habitId}-${date}`,
      habitId,
      date,
      completed: newCompleted
    }
    await saveHabitLog(log)
    setLogs(prev => {
      const filtered = prev.filter(l => !(l.habitId === habitId && l.date === date))
      return [...filtered, log]
    })
  }

  const setMoodEntry = async (m: number, note?: string) => {
    const log: MoodLog = {
      id: `mood-${todayStr}`,
      date: todayStr,
      mood: m,
      note
    }
    await saveMoodLog(log)
    setMood(log)
  }

  return (
    <div className="min-h-screen bg-[#FBFBFA] dark:bg-[#0E0E0E] text-[#111111] dark:text-[#F0F0F0] transition-colors duration-200">
      <div className="max-w-md mx-auto px-4 pb-24 pt-6">
        {activeTab === 'today' && (
          <Today
            habits={habits}
            logs={logs}
            mood={mood}
            onToggleHabit={toggleHabit}
            onSetMood={setMoodEntry}
            dark={dark}
            onToggleDark={() => setDark(d => !d)}
            onDataLoad={loadData}
          />
        )}
        {activeTab === 'week' && <Week habits={habits} logs={logs} />}
        {activeTab === 'settings' && (
          <Settings
            habits={habits}
            onReload={loadData}
          />
        )}
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/80 dark:bg-[#1A1A1A]/80 backdrop-blur-lg border-t border-[#EAEAEA] dark:border-white/10">
        <div className="max-w-md mx-auto flex">
          <TabButton active={activeTab === 'today'} onClick={() => setActiveTab('today')} label="Heute" />
          <TabButton active={activeTab === 'week'} onClick={() => setActiveTab('week')} label="Woche" />
          <TabButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} label="Einstellungen" />
        </div>
      </nav>
    </div>
  )
}

function TabButton({ active, onClick, label }: { active: boolean; onClick: () => void; label: string }) {
  return (
    <button
      onClick={onClick}
      className={`flex-1 py-3 text-sm font-medium transition-colors duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white`}
      aria-label={label}
    >
      <span className={`block text-center ${active ? 'text-[#111111] dark:text-white' : 'text-[#787774]'}`}>
        {label}
      </span>
    </button>
  )
}

import { useState, useEffect, useRef } from 'react'
import { Habit, HabitLog, MoodLog } from '../types'
import { getStreak } from '../db'

interface TodayProps {
  habits: Habit[]
  logs: HabitLog[]
  mood: MoodLog | null
  onToggleHabit: (habitId: string, date: string) => void
  onSetMood: (m: number, note?: string) => void
  dark: boolean
  onToggleDark: () => void
  onDataLoad: () => void
}

const MOOD_EMOJIS = ['😢', '😕', '😐', '🙂', '😊']

export default function Today({ habits, logs, mood, onToggleHabit, onSetMood, dark, onToggleDark, onDataLoad }: TodayProps) {
  const [note, setNote] = useState('')
  const [editingNote, setEditingNote] = useState(false)
  const [animatingId, setAnimatingId] = useState<string | null>(null)
  const noteRef = useRef<HTMLTextAreaElement>(null)

  const todayStr = new Date().toISOString().split('T')[0]
  const streaks = getStreak(habits, logs)

  const completedCount = logs.filter(l => l.completed).length
  const progress = habits.length > 0 ? `${completedCount} von ${habits.length}` : ''

  const formatDate = (dateStr: string) => {
    const d = new Date(dateStr)
    return d.toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long' })
  }

  const handleToggle = (habitId: string) => {
    setAnimatingId(habitId)
    onToggleHabit(habitId, todayStr)
    setTimeout(() => setAnimatingId(null), 300)
  }

  const handleMoodSelect = (m: number) => {
    onSetMood(m, note || undefined)
  }

  useEffect(() => {
    if (editingNote && noteRef.current) {
      noteRef.current.focus()
    }
  }, [editingNote])

  return (
    <div className="space-y-8">
      {/* Header */}
      <header className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight text-[#111111] dark:text-white">
            {formatDate(todayStr)}
          </h1>
          {habits.length > 0 && (
            <p className="mt-1 text-sm text-[#787774]">{progress}</p>
          )}
        </div>
        <button
          onClick={onToggleDark}
          className="w-10 h-10 flex items-center justify-center rounded-lg border border-[#EAEAEA] dark:border-white/10 text-[#787774] hover:bg-[#F7F6F3] dark:hover:bg-white/5 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
          aria-label={dark ? 'Light mode' : 'Dark mode'}
        >
          {dark ? (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="5" />
              <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
            </svg>
          ) : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
            </svg>
          )}
        </button>
      </header>

      {/* Habits */}
      {habits.length === 0 ? (
        <EmptyState />
      ) : (
        <div className="space-y-2">
          {habits.map((habit, i) => {
            const log = logs.find(l => l.habitId === habit.id && l.date === todayStr)
            const completed = log?.completed ?? false
            const streak = streaks[habit.id]
            const isAnimating = animatingId === habit.id

            return (
              <div
                key={habit.id}
                className={`flex items-center gap-4 p-4 rounded-xl border transition-all duration-200 ${
                  completed
                    ? 'border-[#EAEAEA] dark:border-white/10 bg-[#F7F6F3] dark:bg-white/5 opacity-70'
                    : 'border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]'
                } ${isAnimating ? 'scale-95' : ''}`}
                style={{ animationDelay: `${i * 60}ms` }}
              >
                <button
                  onClick={() => handleToggle(habit.id)}
                  className={`w-8 h-8 rounded-md border-2 flex items-center justify-center flex-shrink-0 transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white ${
                    completed
                      ? 'bg-[#111111] dark:bg-white border-[#111111] dark:border-white'
                      : 'border-[#EAEAEA] dark:border-white/20 hover:border-[#111111] dark:hover:border-white'
                  }`}
                  aria-label={`${habit.name} ${completed ? 'abhaken' : 'als erledigt markieren'}`}
                >
                  {completed && (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="20 6 9 17 4 12" />
                    </svg>
                  )}
                </button>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-lg">{habit.emoji}</span>
                    <span className={`font-medium truncate ${completed ? 'text-[#787774] line-through' : 'text-[#111111] dark:text-white'}`}>
                      {habit.name}
                    </span>
                  </div>
                  {streak.current > 0 && (
                    <p className="text-xs text-[#787774] mt-0.5">
                      {streak.current} Tage · Lang: {streak.longest}
                    </p>
                  )}
                </div>

                <div
                  className="w-3 h-3 rounded-full flex-shrink-0"
                  style={{ backgroundColor: habit.color }}
                />
              </div>
            )
          })}
        </div>
      )}

      {/* Mood */}
      <section>
        <h2 className="text-sm font-medium text-[#787774] uppercase tracking-wider mb-3">Stimmung</h2>
        {mood ? (
          <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
            <div className="flex items-center gap-3">
              <span className="text-2xl">{MOOD_EMOJIS[mood.mood - 1]}</span>
              <div className="flex-1">
                <p className="font-medium text-[#111111] dark:text-white">
                  {MOOD_EMOJIS[mood.mood - 1]} {mood.mood}. Stimmung
                </p>
                {mood.note && (
                  <p className="text-sm text-[#787774] mt-1">{mood.note}</p>
                )}
              </div>
              <button
                onClick={() => setEditingNote(true)}
                className="text-sm text-[#787774] hover:text-[#111111] dark:hover:text-white transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white px-2 py-1 rounded"
              >
                Ändern
              </button>
            </div>
          </div>
        ) : (
          <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
            <p className="text-sm text-[#787774] mb-3">Wie war dein Tag?</p>
            <div className="flex gap-2">
              {MOOD_EMOJIS.map((emoji, i) => (
                <button
                  key={i}
                  onClick={() => handleMoodSelect(i + 1)}
                  className="w-11 h-11 flex items-center justify-center text-xl rounded-lg border border-[#EAEAEA] dark:border-white/10 hover:bg-[#F7F6F3] dark:hover:bg-white/5 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
                  aria-label={`Stimmung ${i + 1}: ${emoji}`}
                >
                  {emoji}
                </button>
              ))}
            </div>
          </div>
        )}

        {mood && editingNote && (
          <div className="mt-3 p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
            <textarea
              ref={noteRef}
              value={note}
              onChange={e => setNote(e.target.value)}
              placeholder="Notiz (optional)..."
              rows={2}
              className="w-full text-sm bg-transparent border-none outline-none resize-none text-[#111111] dark:text-white placeholder-[#787774]"
            />
            <div className="flex gap-2 mt-2">
              <button
                onClick={() => { handleMoodSelect(mood.mood, note); setEditingNote(false) }}
                className="px-3 py-1.5 text-sm bg-[#111111] dark:bg-white text-white dark:text-[#111111] rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
              >
                Speichern
              </button>
              <button
                onClick={() => { setNote(''); setEditingNote(false) }}
                className="px-3 py-1.5 text-sm text-[#787774] hover:text-[#111111] dark:hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
              >
                Abbrechen
              </button>
            </div>
          </div>
        )}
      </section>
    </div>
  )
}

function EmptyState() {
  return (
    <div className="py-16 text-center">
      <p className="text-[#787774] text-sm">Noch keine Habits.</p>
      <p className="text-[#787774] text-sm mt-1">Füge in den Einstellungen deine ersten Habits hinzu.</p>
    </div>
  )
}

import { useMemo } from 'react'
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from 'recharts'
import { Habit, HabitLog } from '../types'

interface WeekProps {
  habits: Habit[]
  logs: HabitLog[]
}

export default function Week({ habits, logs }: WeekProps) {
  const weekData = useMemo(() => {
    const days: { label: string; date: string; completed: number; mood?: number }[] = []
    const today = new Date()
    today.setHours(0, 0, 0, 0)

    for (let i = 6; i >= 0; i--) {
      const d = new Date(today)
      d.setDate(d.getDate() - i)
      const dateStr = d.toISOString().split('T')[0]
      const dayLogs = logs.filter(l => l.date === dateStr && l.completed)
      const moodLog = globalThis.localStorage ? null : null // placeholder

      days.push({
        label: d.toLocaleDateString('de-DE', { weekday: 'short' }).replace('.', ''),
        date: dateStr,
        completed: dayLogs.length
      })
    }

    return days
  }, [logs])

  // Mood data for the week
  const moodData = useMemo(() => {
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const days: { label: string; mood?: number }[] = []

    for (let i = 6; i >= 0; i--) {
      const d = new Date(today)
      d.setDate(d.getDate() - i)
      const dateStr = d.toISOString().split('T')[0]
      // Mood would be fetched from DB - simplified for now
      days.push({ label: d.toLocaleDateString('de-DE', { weekday: 'short' }).replace('.', '') })
    }

    return days
  }, [])

  const maxHabits = habits.length || 1

  return (
    <div className="space-y-8">
      <h1 className="text-2xl font-semibold tracking-tight text-[#111111] dark:text-white">Woche</h1>

      {/* Habits per day chart */}
      <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
        <h2 className="text-sm font-medium text-[#787774] uppercase tracking-wider mb-4">Erledigte Habits pro Tag</h2>
        <ResponsiveContainer width="100%" height={200}>
          <BarChart data={weekData} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#EAEAEA" vertical={false} />
            <XAxis
              dataKey="label"
              axisLine={false}
              tickLine={false}
              tick={{ fill: '#787774', fontSize: 12 }}
            />
            <YAxis
              axisLine={false}
              tickLine={false}
              tick={{ fill: '#787774', fontSize: 12 }}
              domain={[0, maxHabits]}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#FFFFFF',
                border: '1px solid #EAEAEA',
                borderRadius: '8px',
                fontSize: '13px'
              }}
              labelStyle={{ color: '#111111' }}
            />
            <Bar
              dataKey="completed"
              fill="#111111"
              radius={[4, 4, 0, 0]}
              maxBarSize={40}
            />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Mood trend */}
      <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
        <h2 className="text-sm font-medium text-[#787774] uppercase tracking-wider mb-4">Stimmungsverlauf</h2>
        <ResponsiveContainer width="100%" height={160}>
          <LineChart data={weekData} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#EAEAEA" vertical={false} />
            <XAxis
              dataKey="label"
              axisLine={false}
              tickLine={false}
              tick={{ fill: '#787774', fontSize: 12 }}
            />
            <YAxis
              axisLine={false}
              tickLine={false}
              tick={{ fill: '#787774', fontSize: 12 }}
              domain={[1, 5]}
              tickCount={5}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#FFFFFF',
                border: '1px solid #EAEAEA',
                borderRadius: '8px',
                fontSize: '13px'
              }}
            />
            <Line
              type="monotone"
              dataKey="mood"
              stroke="#111111"
              strokeWidth={2}
              dot={{ fill: '#111111', r: 4 }}
              activeDot={{ r: 6 }}
            />
          </LineChart>
        </ResponsiveContainer>
        <p className="text-xs text-[#787774] text-center mt-2">
          {weekData.every(d => !d.mood) ? 'Noch keine Stimmungsdaten' : ''}
        </p>
      </div>

      {/* Summary */}
      <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
        <h2 className="text-sm font-medium text-[#787774] uppercase tracking-wider mb-3">Übersicht</h2>
        <div className="space-y-2">
          {habits.map(habit => {
            const habitLogs = logs.filter(l => l.habitId === habit.id && l.completed)
            const weekCount = habitLogs.filter(l => {
              const d = new Date(l.date)
              const today = new Date()
              today.setHours(0, 0, 0, 0)
              const weekStart = new Date(today)
              weekStart.setDate(weekStart.getDate() - 6)
              return d >= weekStart
            }).length

            return (
              <div key={habit.id} className="flex items-center justify-between">
                <span className="flex items-center gap-2 text-sm">
                  <span>{habit.emoji}</span>
                  <span className="text-[#111111] dark:text-white">{habit.name}</span>
                </span>
                <span className="text-sm text-[#787774]">{weekCount}/7 Tage</span>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

import { useState, useRef } from 'react'
import { Habit } from '../types'
import { HABIT_COLORS, EMOJI_OPTIONS } from '../types'
import { saveHabit, deleteHabit } from '../db'

interface SettingsProps {
  habits: Habit[]
  onReload: () => void
}

export default function Settings({ habits, onReload }: SettingsProps) {
  const [showForm, setShowForm] = useState(false)
  const [name, setName] = useState('')
  const [selectedEmoji, setSelectedEmoji] = useState(EMOJI_OPTIONS[0])
  const [selectedColor, setSelectedColor] = useState(HABIT_COLORS[0])
  const [editingId, setEditingId] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const resetForm = () => {
    setName('')
    setSelectedEmoji(EMOJI_OPTIONS[0])
    setSelectedColor(HABIT_COLORS[0])
    setEditingId(null)
    setShowForm(false)
  }

  const handleEdit = (habit: Habit) => {
    setName(habit.name)
    setSelectedEmoji(habit.emoji)
    setSelectedColor(habit.color)
    setEditingId(habit.id)
    setShowForm(true)
    setTimeout(() => inputRef.current?.focus(), 50)
  }

  const handleSubmit = async () => {
    if (!name.trim()) return
    if (editingId) {
      const habit = habits.find(h => h.id === editingId)
      if (habit) {
        await saveHabit({ ...habit, name: name.trim(), emoji: selectedEmoji, color: selectedColor })
      }
    } else {
      const habit: Habit = {
        id: crypto.randomUUID(),
        name: name.trim(),
        emoji: selectedEmoji,
        color: selectedColor,
        createdAt: Date.now()
      }
      await saveHabit(habit)
    }
    resetForm()
    onReload()
  }

  const handleDelete = async (id: string) => {
    await deleteHabit(id)
    onReload()
  }

  return (
    <div className="space-y-8">
      <h1 className="text-2xl font-semibold tracking-tight text-[#111111] dark:text-white">Einstellungen</h1>

      {/* Habits list */}
      <section>
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-sm font-medium text-[#787774] uppercase tracking-wider">Habits</h2>
          <button
            onClick={() => { resetForm(); setShowForm(true) }}
            className="px-3 py-1.5 text-sm bg-[#111111] dark:bg-white text-white dark:text-[#111111] rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
          >
            + Hinzufügen
          </button>
        </div>

        {habits.length === 0 ? (
          <EmptyState onAdd={() => { resetForm(); setShowForm(true) }} />
        ) : (
          <div className="space-y-2">
            {habits.map(habit => (
              <div
                key={habit.id}
                className="flex items-center gap-3 p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]"
              >
                <div
                  className="w-3 h-3 rounded-full flex-shrink-0"
                  style={{ backgroundColor: habit.color }}
                />
                <span className="text-lg flex-shrink-0">{habit.emoji}</span>
                <span className="flex-1 font-medium text-[#111111] dark:text-white truncate">
                  {habit.name}
                </span>
                <button
                  onClick={() => handleEdit(habit)}
                  className="w-8 h-8 flex items-center justify-center rounded-md text-[#787774] hover:bg-[#F7F6F3] dark:hover:bg-white/5 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
                  aria-label={`${habit.name} bearbeiten`}
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
                    <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
                  </svg>
                </button>
                <button
                  onClick={() => handleDelete(habit.id)}
                  className="w-8 h-8 flex items-center justify-center rounded-md text-[#787774] hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-[#9F2F2D] transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
                  aria-label={`${habit.name} löschen`}
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <polyline points="3 6 5 6 21 6" />
                    <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2" />
                  </svg>
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Edit/Add form */}
      {showForm && (
        <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A] space-y-4">
          <h2 className="text-sm font-medium text-[#787774] uppercase tracking-wider">
            {editingId ? 'Habit bearbeiten' : 'Neuer Habit'}
          </h2>

          <div>
            <label className="block text-xs text-[#787774] mb-1.5">Name</label>
            <input
              ref={inputRef}
              type="text"
              value={name}
              onChange={e => setName(e.target.value)}
              placeholder="z.B. Meditieren"
              className="w-full text-base bg-transparent border-b border-[#EAEAEA] dark:border-white/10 outline-none py-2 text-[#111111] dark:text-white placeholder-[#787774] focus:border-[#111111] dark:focus:border-white transition-colors"
              maxLength={30}
            />
          </div>

          <div>
            <label className="block text-xs text-[#787774] mb-1.5">Emoji</label>
            <div className="flex flex-wrap gap-2">
              {EMOJI_OPTIONS.map(emoji => (
                <button
                  key={emoji}
                  onClick={() => setSelectedEmoji(emoji)}
                  className={`w-10 h-10 flex items-center justify-center text-xl rounded-lg border transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white ${
                    selectedEmoji === emoji
                      ? 'border-[#111111] dark:border-white bg-[#F7F6F3] dark:bg-white/10'
                      : 'border-[#EAEAEA] dark:border-white/10 hover:bg-[#F7F6F3] dark:hover:bg-white/5'
                  }`}
                  aria-label={emoji}
                >
                  {emoji}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs text-[#787774] mb-1.5">Farbe</label>
            <div className="flex flex-wrap gap-2">
              {HABIT_COLORS.map(color => (
                <button
                  key={color}
                  onClick={() => setSelectedColor(color)}
                  className={`w-8 h-8 rounded-lg border-2 transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white ${
                    selectedColor === color
                      ? 'border-[#111111] dark:border-white scale-110'
                      : 'border-transparent hover:scale-105'
                  }`}
                  style={{ backgroundColor: color }}
                  aria-label={`Farbe ${color}`}
                />
              ))}
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <button
              onClick={handleSubmit}
              disabled={!name.trim()}
              className="px-4 py-2 text-sm bg-[#111111] dark:bg-white text-white dark:text-[#111111] rounded-md disabled:opacity-40 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
            >
              {editingId ? 'Speichern' : 'Hinzufügen'}
            </button>
            <button
              onClick={resetForm}
              className="px-4 py-2 text-sm text-[#787774] hover:text-[#111111] dark:hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] dark:focus-visible:ring-white"
            >
              Abbrechen
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

function EmptyState({ onAdd }: { onAdd: () => void }) {
  return (
    <div className="py-12 text-center border border-dashed border-[#EAEAEA] dark:border-white/10 rounded-xl">
