            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#FFFFFF',
                border: '1px solid #EAEAEA',
                borderRadius: '8px',
                fontSize: '13px'
              }}
              labelStyle={{ color: '#111111' }}
            />
            <Bar
              dataKey="completed"
              fill="#111111"
              radius={[4, 4, 0, 0]}
              maxBarSize={40}
