        </ResponsiveContainer>
        {!hasMoodData && (
          <p className="text-xs text-[#787774] text-center mt-2">Noch keine Stimmungsdaten</p>
        )}
      </div>

      {/* Summary */}
      <div className="p-4 rounded-xl border border-[#EAEAEA] dark:border-white/10 bg-white dark:bg-[#1A1A1A]">
